head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL40203";
scwin.selFormNo = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.corpUsrTpCd

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "ipt_setChrg", attr: "__items", fn: function () { return [[String((dma_pageContext.get("isurCd") ?? "")), ""]]; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_10", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'); } }, { id: "c_otherwise_102", fn: function(){ return (!(((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'))); } }, { id: "c_otherwise_116", fn: function(){ return (!(((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'))); } }, { id: "c_when_42_r1_txt", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '11' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '16' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '17' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '19'); } }, { id: "c_when_43_r1_txt", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '21' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '24'); } }, { id: "c_when_53_r1_txt", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '11' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '19'); } }, { id: "c_when_54_r1_txt", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '21' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '24'); } }, { id: "span_101_r1", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'); } }, { id: "c_otherwise_102_r1", fn: function(){ return (!(((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'))); } }, { id: "span_115_r1", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'); } }, { id: "c_otherwise_116_r1", fn: function(){ return (!(((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'))); } }, { id: "c_when_46_r2_txt", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '11' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '16' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '17' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '19'); } }, { id: "c_when_47_r2_txt", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '21' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '24'); } }, { id: "c_when_57_r2_txt", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '11' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '19'); } }, { id: "c_when_58_r2_txt", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '21' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '24'); } }, { id: "span_101_r2", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'); } }, { id: "c_otherwise_102_r2", fn: function(){ return (!(((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'))); } }, { id: "span_115_r2", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'); } }, { id: "c_otherwise_116_r2", fn: function(){ return (!(((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_setChrg", fn: function () { return String((dma_pageContext.get("isurCd") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_corpDisclsChrgForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil40203.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_setChrg_onclick
 * @description ipt_setChrg 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_setChrg_onclick = async function(e){
    try {
        await scwin.getChrgList('__self.value')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40203.ipt_setChrg_onclick' }); }
};

/**
 * @method
 * @name slc_selEmail_onchange
 * @description slc_selEmail 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_selEmail_onchange = function(e){
    try {
        $c.fil.selEmail($c.util.getComponent("slc_selEmail"), $c.util.getComponent("ipt_email2"));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40203.slc_selEmail_onchange' }); }
};

/**
 * @method
 * @name btn_PopZipCode_onclick
 * @description 「우편번호」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_PopZipCode_onclick = async function(e){
    try {
        await scwin.popZipCode(0)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40203.btn_PopZipCode_onclick' }); }
};

/**
 * @method
 * @name slc_selEmail_r1_onchange
 * @description slc_selEmail_r1 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_selEmail_r1_onchange = function(e){
    try {
        $c.fil.selEmail($c.util.getComponent("slc_selEmail_r1"), $c.util.getComponent("ipt_email2_r1"));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40203.slc_selEmail_r1_onchange' }); }
};

/**
 * @method
 * @name btn_PopZipCode_r1_onclick
 * @description 「우편번호」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_PopZipCode_r1_onclick = async function(e){
    try {
        await scwin.popZipCode(1)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40203.btn_PopZipCode_r1_onclick' }); }
};

/**
 * @method
 * @name slc_selEmail_r2_onchange
 * @description slc_selEmail_r2 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_selEmail_r2_onchange = function(e){
    try {
        $c.fil.selEmail($c.util.getComponent("slc_selEmail_r2"), $c.util.getComponent("ipt_email2_r2"));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40203.slc_selEmail_r2_onchange' }); }
};

/**
 * @method
 * @name btn_PopZipCode_r2_onclick
 * @description 「우편번호」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_PopZipCode_r2_onclick = async function(e){
    try {
        await scwin.popZipCode(2)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40203.btn_PopZipCode_r2_onclick' }); }
};

/**
 * @method
 * @name btn_ApplyJoin_r2_onclick
 * @description 「가입신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ApplyJoin_r2_onclick = async function(e){
    try {
        await scwin.applyJoin()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40203.btn_ApplyJoin_r2_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_r2_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_GoURL_r2_onclick = function(e){
    try {
        scwin.goURL('cancel')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40203.btn_GoURL_r2_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ApplyJoin
 * @description Apply Join 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ApplyJoin = async function (action) {
    const sbmOptions = {
        id: "tx_fn_ApplyJoin",
        method: "post",
        action: action ?? "/register/corpDiscls.do",
        ref: "dma_ApplyJoinReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_getChrgList_xhr
 * @description get Chrg List xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_getChrgList_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_getChrgList_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_getChrgList_xhr", unresolved: "action:self_submit:tx_getChrgList_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name popZipCode
 * @description pop Zip Code 처리
 * @param {*} _selNo _selNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popZipCode = async function (_selNo) {
    scwin.selFormNo = _selNo;
    const zipSearchURL = '/ui/jsp/JLDINF90009.xml';
    scwin.setZipCode_recv(await $c.win.openPopup(zipSearchURL, { id: "zipWin", scrollbars: false, resizable: false, width: "445", height: "600", type: "pageFramePopup" }, Object.assign({ method: "loadInitPage" }, { selFormNo: (typeof scwin.selFormNo !== 'undefined' ? scwin.selFormNo : undefined) })));
};

/**
 * @method
 * @name setZipCode
 * @description set Zip Code 처리
 * @param {*} _zipCode _zipCode
 * @param {*} _address _address
 * @returns {void}
 * @hidden N
 */
scwin.setZipCode = function (_zipCode, _address) {
    $c.util.getComponent(["ipt_locZipcd", "ipt_locZipcd_r1", "ipt_locZipcd_r2"][scwin.selFormNo]).setValue(_zipCode);
    $c.util.getComponent(["ipt_locAddr", "ipt_locAddr_r1", "ipt_locAddr_r2"][scwin.selFormNo]).setValue(_address);
};

/**
 * @method
 * @name applyJoin
 * @description apply Join 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.applyJoin = async function () {
    let loopCnt;
    loopCnt = 3;
    if ($c.util.getComponent('ipt_chrgNm_r1').getValue() !== '') {
        loopCnt = 2;
    }
    if ($c.util.getComponent('ipt_chrgNm_r2').getValue() !== '') {
        loopCnt = 3;
    }
    for (let i = 0; i < loopCnt; i++) {
        if (!await scwin.chkForm(i)) {
            return;
        }
    }
    $c.util.getComponent("dma_ApplyJoinReq").set("method", 'registerCorpDisclsChrg');
    await scwin.tx_fn_ApplyJoin('corpDiscls.do');
};

/**
 * @method
 * @name chkForm
 * @description chk Form 처리
 * @param {*} formNo formNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkForm = async function (formNo) {
    const frm = (document.corpDisclsChrgForm || { elements: [] });
    if (await $c.fil.checkRequired($c.util.getComponent(["ipt_chrgNm", "ipt_chrgNm_r1", "ipt_chrgNm_r2"][formNo]))) {
        return false;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "성명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent(["ipt_chrgNm", "ipt_chrgNm_r1", "ipt_chrgNm_r2"][formNo]))) {
        return false;
    }
    if (await $c.fil.checkRequired($c.util.getComponent(["ipt_jobtitlNm", "ipt_jobtitlNm_r1", "ipt_jobtitlNm_r2"][formNo]))) {
        return false;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "직위"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent(["ipt_jobtitlNm", "ipt_jobtitlNm_r1", "ipt_jobtitlNm_r2"][formNo]))) {
        return false;
    }
    if (await $c.fil.checkRequired($c.util.getComponent(["ipt_depNm", "ipt_depNm_r1", "ipt_depNm_r2"][formNo]))) {
        return false;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "부서"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent(["ipt_depNm", "ipt_depNm_r1", "ipt_depNm_r2"][formNo]))) {
        return false;
    }
    if (await $c.fil.checkRequired($c.util.getComponent(["ipt_telNo1", "ipt_telNo1_r1", "ipt_telNo1_r2"][formNo])) || await $c.fil.checkRequired($c.util.getComponent(["ipt_telNo2", "ipt_telNo2_r1", "ipt_telNo2_r2"][formNo])) || await $c.fil.checkRequired($c.util.getComponent(["ipt_telNo3", "ipt_telNo3_r1", "ipt_telNo3_r2"][formNo]))) {
        return false;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent(["ipt_telNo1", "ipt_telNo1_r1", "ipt_telNo1_r2"][formNo])) && $c.fil.isNumberInput($c.util.getComponent(["ipt_telNo2", "ipt_telNo2_r1", "ipt_telNo2_r2"][formNo])) && $c.fil.isNumberInput($c.util.getComponent(["ipt_telNo3", "ipt_telNo3_r1", "ipt_telNo3_r2"][formNo])))) {
        await $c.win.alert('유선전화번호는 숫자만 입력하세요');
        return false;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent(["ipt_chrgInnrNo", "ipt_chrgInnrNo_r1", "ipt_chrgInnrNo_r2"][formNo])))) {
        await $c.win.alert('내선은 숫자만 입력하세요');
        return false;
    }
    if (await $c.fil.checkRequired($c.util.getComponent(["slc_cellphoneNo1", "slc_cellphoneNo1_r1", "slc_cellphoneNo1_r2"][formNo])) || await $c.fil.checkRequired($c.util.getComponent(["ipt_cellphoneNo2", "ipt_cellphoneNo2_r1", "ipt_cellphoneNo2_r2"][formNo])) || await $c.fil.checkRequired($c.util.getComponent(["ipt_cellphoneNo3", "ipt_cellphoneNo3_r1", "ipt_cellphoneNo3_r2"][formNo]))) {
        return false;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent(["slc_cellphoneNo1", "slc_cellphoneNo1_r1", "slc_cellphoneNo1_r2"][formNo])) && $c.fil.isNumberInput($c.util.getComponent(["ipt_cellphoneNo2", "ipt_cellphoneNo2_r1", "ipt_cellphoneNo2_r2"][formNo])) && $c.fil.isNumberInput($c.util.getComponent(["ipt_cellphoneNo3", "ipt_cellphoneNo3_r1", "ipt_cellphoneNo3_r2"][formNo])))) {
        await $c.win.alert('휴대전화번호는 숫자만 입력하세요');
        return false;
    }
