 */
scwin.onCompleteResponse = async function (responseXML) {
    if ((responseXML == null) || ('' === responseXML)) {
        await $c.win.alert("데이터를 불러올 수 없습니다. \n 해당기업의 유가증권 또는 코스닥 공시책임자/담당자 정보가 존재하지 않습니다.");
    } else {
        const xmlDoc = xmlHttp.responseXML;
        for (let i = 0; i < xmlDoc.getElementsByTagName("chargers")[0].childNodes.length; i++) {
            const charger = xmlDoc.getElementsByTagName("charger")[i];
            const chrgNm = charger.getElementsByTagName("chrgNm")[0].childNodes[0].nodeValue;
            const jobtitlNm = charger.getElementsByTagName("jobtitlNm")[0].childNodes[0].nodeValue;
