            const birthdd = charger.getElementsByTagName("birthdd")[0].childNodes[0].nodeValue;
            const eduCompltYn = charger.getElementsByTagName("eduCompltYn")[0].childNodes[0].nodeValue;
            const eduCompltDd = charger.getElementsByTagName("eduCompltDd")[0].childNodes[0].nodeValue;
            const eduCrsNm = charger.getElementsByTagName("eduCrsNm")[0].childNodes[0].nodeValue;
            const disclsProfsYn = charger.getElementsByTagName("disclsProfsYn")[0].childNodes[0].nodeValue;
            const chrgDesignDd = charger.getElementsByTagName("chrgDesignDd")[0].childNodes[0].nodeValue;
            const locZipcd = charger.getElementsByTagName("locZipcd")[0].childNodes[0].nodeValue;
