            const locDtlAddr = charger.getElementsByTagName("locDtlAddr")[0].childNodes[0].nodeValue;
            $c.util.getComponent(["ipt_chrgNm", "ipt_chrgNm_r1", "ipt_chrgNm_r2"][i]).setValue(chrgNm);
            $c.util.getComponent(["ipt_jobtitlNm", "ipt_jobtitlNm_r1", "ipt_jobtitlNm_r2"][i]).setValue(jobtitlNm);
            $c.util.getComponent(["ipt_depNm", "ipt_depNm_r1", "ipt_depNm_r2"][i]).setValue(depNm);
            if ('' !== telNo) {
                const telNoArr = telNo.split("-");
                $c.util.getComponent(["ipt_telNo1", "ipt_telNo1_r1", "ipt_telNo1_r2"][i]).setValue(telNoArr[0]);
                $c.util.getComponent(["ipt_telNo2", "ipt_telNo2_r1", "ipt_telNo2_r2"][i]).setValue(telNoArr[1]);
                $c.util.getComponent(["ipt_telNo3", "ipt_telNo3_r1", "ipt_telNo3_r2"][i]).setValue(telNoArr[2]);
            }
            $c.util.getComponent(["ipt_chrgInnrNo", "ipt_chrgInnrNo_r1", "ipt_chrgInnrNo_r2"][i]).setValue(chrgInnrNo);
            if ('' !== cellphoneNo) {
